mapper.select:
SELECT AM.*, ( SELECT SE.AVATAR FROM SYS_EXTENSION SE WHERE SE.ENV_CODE = AM.ENV_CODE AND (SE.DELETED = 0 OR SE.DELETED IS NULL) AND AM.PROVIDER IS NOT NULL AND AM.PROVIDER != '' AND (SE.PROVIDER_CODE = AM.PROVIDER OR SE.EXTENSION_KEY = AM.PROVIDER) ORDER BY CASE WHEN SE.PROVIDER_CODE = AM.PROVIDER THEN 0 ELSE 1 END LIMIT 1 ) AS providerAvatar FROM `AI_MODEL` AM WHERE 1=1
AND AM.ENV_CODE = #{req.envCode}
AND AM.PROVIDER = #{req.supplier}
AND AM.MODEL_NAME LIKE CONCAT('%', #{req.modelName}, '%')
AND AM.MODEL_KEY = #{req.modelKey}
AND AM.ACCOUNT_KEY = #{req.accountKey}
AND AM.STATUS = #{req.status}
ORDER BY AM.PROVIDER DESC, AM.MODEL_TYPE DESC
